import { IActionOrTriggerItem, createActionOrTriggerButtonRender } from '@src/components/trigger-list-action-list-common/ITriggerList-IActionList-common.intf';
import { createActionHandler } from '@droid/project-v2-interface';
import { actionScriptUtils } from '@droid/project';
import { Log } from '@fanfanlo';

const fileLog = new Log(true, 'script-action-v2');
fileLog.log('script-action-v2 模块加载');

// 创建 V2 处理器
const onSelectV2 = createActionHandler(() => {
  fileLog.log('创建默认 script action');
  const defaultData = actionScriptUtils.createDefaultData();
  fileLog.log('默认 script action 创建完成:', JSON.stringify(defaultData));
  return defaultData;
});

// 复用 V1 的 UI 配置和 i18n，但使用 V2 处理器
export const scriptActionItemV2: IActionOrTriggerItem = {
  id: "script-action-item-v2-ce8c",
  i18nNs: "homepage/components/page/action-list/groups/script/script-action/content",
  nameKey: "content.name",
  group: "scriptActionItem.group",
  descriptionKey: "content.description",
  type: "action",
  LinkRender: createActionOrTriggerButtonRender(onSelectV2)
};
